    private static final java.util.Set<Integer> CODE_POINTS = new java.util.HashSet<>();
    static { CHARACTERS.codePoints().forEach(CODE_POINTS::add); }
    static final int COUNT = CODE_POINTS.size();
    static boolean permits(String word, boolean personallyUsed) {
        if (word == null || word.isEmpty()) return false;
        if (personallyUsed) return true;
        for (int i=0; i<word.length();) {
            int cp = word.codePointAt(i);
            if (!CODE_POINTS.contains(cp)) return false;
            i += Character.charCount(cp);
        }
        return true;
    }
